import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { createForks, teardownForks } from "@tigrisdata/agent-kit";

const PROJECT_DIR = "/home/user/seeded-fork";
const DATA_DIR = join(PROJECT_DIR, "data");
const SEED_BUCKET = "seed-corpus";
const FORKS_JSON_PATH = join(PROJECT_DIR, "forks.json");

async function run() {
  const s3Client = new S3Client({
    region: "auto",
    endpoint: "https://t3.storage.dev",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  let forkSet: any = undefined;

  try {
    // 1. Seed the corpus
    const files = ["a.txt", "b.txt", "c.txt"];
    for (const file of files) {
      const content = await readFile(join(DATA_DIR, file));
      await s3Client.send(
        new PutObjectCommand({
          Bucket: SEED_BUCKET,
          Key: file,
          Body: content,
        })
      );
    }

    // 2. Create forks
    const result = await createForks(SEED_BUCKET, 2, {
      prefix: "eval-dispatch",
      credentials: { role: "ReadOnly" },
    });

    if (result.error) {
      throw result.error;
    }

    forkSet = result.forkSet;

    // 3. Write fork bucket names to forks.json
    const forkNames = forkSet.forks.map((f: any) => f.bucket);
    const output = { forks: forkNames };
    await writeFile(FORKS_JSON_PATH, JSON.stringify(output), "utf-8");

    // Success exit 0 is default if no error
  } finally {
    // 4. Teardown forks
    if (forkSet) {
      await teardownForks(forkSet);
    }
  }
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});

