  let forkSet: any = undefined;

  try {
    // 0. Ensure bucket exists with snapshots enabled
    // First, try to remove it if it exists (best effort)
    await removeBucket(SEED_BUCKET, { force: true });

    // Wait a bit for deletion to propagate
    await new Promise(resolve => setTimeout(resolve, 5000));

    // Create it with snapshots enabled
    const createResult = await createBucket(SEED_BUCKET, { enableSnapshot: true });
    if (createResult.error) {
      // If still inaccessible, wait more and retry once
      console.log("Bucket creation failed, retrying once...");
      await new Promise(resolve => setTimeout(resolve, 5000));
      const secondTry = await createBucket(SEED_BUCKET, { enableSnapshot: true });
      if (secondTry.error) throw secondTry.error;
    }

    // 1. Seed the corpus
    const files = ["a.txt", "b.txt", "c.txt"];
    for (const file of files) {
      const content = await readFile(join(DATA_DIR, file));
      await s3Client.send(
