    // 2. Create forks
    const result = await createForks(SEED_BUCKET, 2, {
      prefix: "eval-dispatch",
      credentials: { role: "ReadOnly" },
    });

    if (result.error) {
      throw result.error;
    }

    forkSet = result.forkSet;

    // 3. Write fork bucket names to forks.json
    const forkNames = forkSet.forks.map((f: any) => f.bucket);
    const output = { forks: forkNames };
    await writeFile(FORKS_JSON_PATH, JSON.stringify(output), "utf-8");

    // Success exit 0 is default if no error
  } finally {
    // 4. Teardown forks
    if (forkSet) {
      await teardownForks(forkSet);
    }
  }
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});

