          (args.request as any).headers["X-Tigris-Enable-Snapshot"] = "true";
          return next(args);
        },
        { step: "build" }
      );
      await s3Client.send(createBucketCmd);
      console.log("Bucket created.");
    } catch (e: any) {
      if (e.name === 'BucketAlreadyExists') {
        console.log("Bucket already exists.");
      } else {
        throw e;
      }
    }

    // 1. Seed the corpus
    const files = ["a.txt", "b.txt", "c.txt"];
    for (const file of files) {
      const content = await readFile(join(DATA_DIR, file));
      await s3Client.send(
        new PutObjectCommand({
          Bucket: ACTUAL_BUCKET,
          Key: file,
          Body: content,
        })
      );
    }

    // 2. Create forks
    const result = await createForks(ACTUAL_BUCKET, 2, {
      prefix: "eval-dispatch",
      credentials: { role: "ReadOnly" },
    });

    if (result.error) {
      throw result.error;
    }

    forkSet = result.data;

    // 3. Write fork bucket names to forks.json
    const forkNames = forkSet.forks.map((f: any) => f.bucket);
    const output = { forks: forkNames };
    await writeFile(FORKS_JSON_PATH, JSON.stringify(output), "utf-8");

    // Success exit 0 is default if no error
  } finally {
    // 4. Teardown forks
    if (forkSet) {
      await teardownForks(forkSet);
    }
  }
